                  <button id="add-a-btn" class="flex-1 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-black text-sm shadow-md shadow-emerald-600/30 active:scale-95 transition-all">+1 \u5F97\u5206</button>
